from pathlib import Path
import json,html,re,importlib.util
root=Path(__file__).resolve().parents[1]
article_spec=importlib.util.spec_from_file_location('article_renderer',root/'scripts/article-pages.py');articles=importlib.util.module_from_spec(article_spec);article_spec.loader.exec_module(articles)
e=lambda v:html.escape(str(v),quote=True)
def header(home=False):
 return '<a class="skip-link" href="#konten">Langsung ke isi</a><header class="site-header wrap"><a class="brand" href="/" aria-label="Gendut Store, beranda"><img src="/assets/gendut-store-logo.webp" width="800" height="267" alt="Gendut Store"></a><nav aria-label="Navigasi utama"><a href="/#pilihan-game">Pilihan game</a><a href="/#cara-beli">Cara beli</a><a href="/#faq">FAQ</a></nav><a class="button small" href="https://gendutstore.com/games">Buka katalog <span aria-hidden="true">↗</span></a></header>'
def footer():
 return '<footer class="site-footer wrap"><div><a class="brand" href="/"><img src="/assets/gendut-store-logo.webp" width="800" height="267" alt="Gendut Store" loading="lazy"></a><p>Pilihan game dan voucher.<br>Pembelian dilanjutkan di situs utama Gendut Store.</p></div><nav aria-label="Navigasi footer"><a href="https://gendutstore.com/games">Katalog pusat ↗</a><a href="/#cara-beli">Cara beli</a><a href="/#faq">Pertanyaan umum</a><a href="https://gendutstore.com/terms">Syarat &amp; ketentuan ↗</a></nav><p class="footer-note">Pilih sesuai akunmu. Periksa detail produk sebelum melanjutkan pembelian.</p></footer>'
def faq(items):return '<div class="faq-list">'+''.join('<details><summary>'+e(p['question'])+'<span aria-hidden="true">+</span></summary><p>'+e(p['answer'])+'</p></details>' for p in items)+'</div>'
def head(p):
 return '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+e(p['title'])+'</title><meta name="description" content="'+e(p['description'])+'"><meta name="robots" content="index, follow, max-image-preview:large"><meta name="theme-color" content="#110b1c"><meta property="og:type" content="website"><meta property="og:locale" content="id_ID"><meta property="og:site_name" content="Gendut Store — Pilihan Game &amp; Voucher"><meta property="og:title" content="'+e(p['title'])+'"><meta property="og:description" content="'+e(p['description'])+'"><meta name="twitter:card" content="summary"><link rel="icon" href="/assets/icon.svg" type="image/svg+xml"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/assets/theme-dark.css"><script src="/script.js" defer></script></head><body>'
def discovery_hero(p,search):
 h=p['hero'];primary=h['primary_cta'];secondary=h['secondary_cta'];labels={0:'Mobile Legends',1:'Free Fire',3:'VALORANT'}
 shortcuts=''.join('<a href="'+e(p['cards'][i]['path'])+'"><img src="'+e(p['cards'][i]['image']['path'])+'" width="44" height="44" alt="" decoding="async"><span>'+e(label)+'</span></a>' for i,label in labels.items())
 return '<section class="hero wrap landing-hero"><div class="hero-copy"><p class="eyebrow">Gendut Store · Game &amp; voucher</p><h1>'+e(p['h1']).replace('Lanjut mabar.','<span>Lanjut mabar.</span>')+'</h1><p class="lead">'+e(h['lede'])+'</p><div class="hero-discovery">'+search+'<nav class="game-shortcuts" aria-label="Pintasan panduan game">'+shortcuts+'</nav></div><div class="actions"><a class="button" href="'+e(primary['href'])+'">'+e(primary['label'])+' <span aria-hidden="true">↗</span></a><a class="text-link" href="'+e(secondary['href'])+'">'+e(secondary['label'])+' <span aria-hidden="true">↓</span></a></div></div><div class="hero-art"><span class="hero-stage" aria-hidden="true"></span><span class="hero-orbit" aria-hidden="true"></span><img src="/assets/gendut-mascot-controller.webp" width="1000" height="1000" alt="Maskot Gendut Store duduk memegang controller dengan konsol putih di sampingnya" fetchpriority="high"></div></section>'
def render_pages(data):
 homefaq=data['pages'][0].get('faq',[])
 rendered={}
 for p in data['pages']:
  if p.get('page_type')=='article':
   content=articles.render_article(p['approved_document'],data['pages'])
  elif p.get('page_type')=='article_index':
   content=articles.render_index([q for q in data['pages'] if q.get('page_type')=='article'])
  elif p.get('approved_document'):
   doc=p['approved_document'];paragraphs=''.join('<p>'+e(t).replace('\n','<br>')+'</p>' for t in doc['content'].split('\n\n') if t.strip())
   content='<main id="konten" class="wrap section"><p class="eyebrow">Gendut Store · Panduan game</p><h1>'+e(doc['title'])+'</h1><p class="lead">'+e(doc['description'])+'</p><article class="article-section approved-copy">'+paragraphs+'</article><a class="button" href="https://gendutstore.com/games">Buka katalog Gendut Store ↗</a><p class="catalog-note"><a href="/">Kembali ke beranda</a></p></main>'
  elif p['path']=='/':
   cards=''.join('<article class="game-card" data-game="'+e(c['name'])+'" data-category="'+c['category']+'"><a href="'+c['path']+'"><div class="game-art"><img src="'+c['image']['path']+'" width="'+str(c['image']['width'])+'" height="'+str(c['image']['height'])+'" alt="" loading="lazy" decoding="async"></div><div class="game-copy"><span class="category">'+('Voucher' if c['category']=='voucher' else 'Top up game')+'</span><h3>'+e(c['name'])+'</h3><p>'+e(c['description'])+'</p><span class="card-link">'+e(c['label'])+' <span aria-hidden="true">↗</span></span></div></a></article>' for c in p['cards'])
   content='''<main id="konten"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span aria-hidden="true">✦</span> Gendut Store · Game &amp; voucher</p><h1>Pilihan top up game dan voucher <span>Gendut Store</span></h1><p class="lead">Dari game untuk mabar sampai voucher pilihanmu, mulai dengan produk yang sesuai akun. Jelajahi pilihan di bawah, lalu buka situs utama Gendut Store untuk membaca detail dan melanjutkan pembelian.</p><div class="actions"><a class="button" href="https://gendutstore.com/games">Buka katalog Gendut Store <span aria-hidden="true">↗</span></a><a class="text-link" href="#pilihan-game">Lihat pilihan game <span aria-hidden="true">↓</span></a></div><p class="hero-note">Pilih game, cek data akun, lalu lanjutkan di gendutstore.com.</p></div><div class="hero-art"><span class="hero-orbit" aria-hidden="true"></span><span class="spark s1" aria-hidden="true">✦</span><span class="spark s2" aria-hidden="true">✧</span><img src="/assets/gendut-mascot-controller.webp" width="1000" height="1000" alt="Maskot Gendut Store duduk sambil memegang controller, dengan konsol putih dan kartu berwarna di sampingnya" fetchpriority="high"><span class="art-note">GAME ON. <b>PILIHANMU SIAP DICEK.</b></span></div></section><section class="benefits wrap" aria-labelledby="benefit-title"><div class="benefits-heading"><p class="eyebrow">Pilih. Cocokkan. Lanjutkan.</p><h2 id="benefit-title">Pilihan game dan voucher,<br>lebih mudah ditelusuri.</h2></div><div class="benefit-row"><article><span>01</span><h3>Mulai dari nama game.</h3><p>Temukan tautan ke pilihan game dan voucher tanpa perlu menebak kategori produknya.</p></article><article><span>02</span><h3>Buka detail yang sesuai.</h3><p>Setiap kartu membuka panduan game untuk membantu kamu mengecek akun sebelum melanjutkan ke produk Gendut Store.</p></article><article><span>03</span><h3>Cek sebelum melanjutkan.</h3><p>Gunakan panduan singkat di halaman ini untuk mencocokkan ID, server, region atau edisi yang diminta produk.</p></article></div></section><section class="games-section" id="pilihan-game"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Temukan pilihanmu</p><h2>Mulai dari game<br>yang kamu mainkan.</h2></div><p>Pilih game atau voucher yang ingin kamu lihat. Baca deskripsinya di situs utama sebelum menentukan pilihan untuk akunmu.</p></div><div class="search-tools" id="game-tools" hidden><div class="search-box"><label for="game-search" class="sr-only">Cari nama game atau voucher</label><span aria-hidden="true">⌕</span><input id="game-search" type="search" placeholder="Cari game atau voucher…" autocomplete="off" aria-controls="game-grid"><button type="button" id="search-clear" aria-label="Hapus pencarian" hidden>×</button></div><div class="filters" role="group" aria-label="Kategori pilihan"><button type="button" data-filter="all" aria-pressed="true">Semua</button><button type="button" data-filter="topup" aria-pressed="false">Top up game</button><button type="button" data-filter="voucher" aria-pressed="false">Voucher</button></div></div><p id="game-count" class="result-count" role="status" aria-live="polite" aria-atomic="true" hidden></p><div class="game-grid" id="game-grid">'''+cards+'''</div><div id="game-empty" class="empty-state" hidden><h3>Belum ada pilihan yang cocok.</h3><p>Coba nama lain atau lihat pilihan selengkapnya di katalog pusat.</p><button type="button" id="reset-search" class="button secondary">Tampilkan semua pilihan</button></div><p class="catalog-note">Belum menemukan game yang kamu cari? <a href="https://gendutstore.com/games">Jelajahi katalog Gendut Store ↗</a></p></div></section><section class="how wrap section" id="cara-beli"><div><p class="eyebrow">Sebelum lanjut beli</p><h2>Tiga langkah sebelum<br>melanjutkan pembelian.</h2><p class="section-intro">Mulai dari pilihan yang tepat, lalu cocokkan detailnya dengan akunmu.</p></div><ol class="steps"><li><span>01</span><div><h3>Buka produk pilihanmu.</h3><p>Pilih game atau voucher, lalu baca deskripsi, platform dan ketentuan yang tercantum.</p></div></li><li><span>02</span><div><h3>Cocokkan data akun.</h3><p>Isi data sesuai kolom yang diminta. Cek lagi ID, server, region atau edisi; kebutuhan tiap produk dapat berbeda.</p></div></li><li><span>03</span><div><h3>Periksa pilihan, lalu lanjutkan.</h3><p>Tinjau kembali produk dan isianmu. Ikuti langkah pemesanan serta pembayaran yang tersedia di situs utama Gendut Store.</p></div></li></ol></section><section class="faq-section wrap section" id="faq"><div><p class="eyebrow">Biar makin jelas</p><h2>Pertanyaan umum.</h2><p class="section-intro">Cari tahu sebelum menentukan pilihan untuk akunmu.</p></div>'''+faq(homefaq)+'''</section><section class="closing wrap"><p class="eyebrow">Pilihanmu, langkah berikutnya</p><h2>Sudah tahu<br>mau pilih yang mana?</h2><p>Buka katalog Gendut Store, temukan game atau voucher yang sesuai,<br class="desktop-only"> dan cek kembali detailnya sebelum melanjutkan.</p><a class="button" href="https://gendutstore.com/games">Buka katalog Gendut Store <span aria-hidden="true">↗</span></a></section></main>'''
  else:
   c=p['copy'];im=p['image'];facts=''.join('<div><dt>'+e(f['label'])+'</dt><dd>'+e(f['value'])+'</dd></div>' for f in c['product_facts']);sections=''.join('<section class="article-section"><h2>'+e(s['heading'])+'</h2>'+''.join('<p>'+e(a)+'</p>' for a in s['paragraphs'])+'</section>' for s in c['sections']);steps='<ol class="steps">'+''.join('<li><span>0'+str(i+1)+'</span><div><h3>'+e(v['title'])+'</h3><p>'+e(v['text'])+'</p></div></li>' for i,v in enumerate(c['steps']))+'</ol>';links=''.join('<a href="'+q['path']+'">'+e(q.get('copy',{}).get('game',q['title']))+' <span aria-hidden="true">↗</span></a>' for q in data['pages'][1:] if q['path']!=p['path'] and q['path'].startswith('/game/'))
   content='<main id="konten" class="game-page"><div class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Beranda</a><span aria-hidden="true">/</span><span aria-current="page">'+e(c['game'])+'</span></nav><section class="game-hero"><div><p class="eyebrow">Panduan pilihan game &amp; voucher</p><h1>'+e(c['h1'])+'</h1><p class="lead">'+e(c['intro'])+'</p><a class="button" href="'+e(c['cta']['url'])+'">'+e(c['cta']['label'])+' <span aria-hidden="true">↗</span></a><p class="hero-note">Pilihan produk dan pembelian dilanjutkan di gendutstore.com.</p></div><div class="product-visual"><img src="'+im['path']+'" width="'+str(im['width'])+'" height="'+str(im['height'])+'" alt="" fetchpriority="high"></div></section><dl class="product-facts">'+facts+'</dl><div class="article-layout"><article>'+sections+'<section class="article-section"><h2>Langkah menuju produk pilihanmu</h2>'+steps+'</section><section class="article-section"><h2>Pertanyaan tentang '+e(c['game'])+'</h2>'+faq(c['faq'])+'</section></article><aside class="product-aside"><p class="eyebrow">Lanjut ke situs utama</p><h2>Sudah cocok<br>dengan akunmu?</h2><p>Baca pilihan terbaru dan petunjuk produk sebelum melanjutkan pemesanan.</p><a class="button" href="'+e(c['cta']['url'])+'">'+e(c['cta']['label'])+' ↗</a><a class="text-link" href="/#pilihan-game">Lihat game lainnya</a></aside></div><section class="related"><p class="eyebrow">Pilihan lainnya</p><h2>Game lain yang kamu mainkan?</h2><nav aria-label="Panduan game lainnya">'+links+'</nav></section></div></main>'
  if p['path']=='/' and not p.get('approved_document'):
   hero=p.get('hero',{})
   content=re.sub(r'(<p class="lead">).*?(</p>)',lambda m:m[1]+e(hero.get('lede',''))+m[2],content,count=1,flags=re.S)
   hero_end=content.index('</section>');hero_html=content[:hero_end]
   primary=hero['primary_cta'];secondary=hero['secondary_cta']
   hero_html=re.sub(r'<a class="button"[^>]*>.*?</a>',lambda _: '<a class="button" href="'+e(primary['href'])+'">'+e(primary['label'])+' <span aria-hidden="true">↗</span></a>',hero_html,count=1,flags=re.S)
   hero_html=re.sub(r'<a class="text-link"[^>]*>.*?</a>',lambda _: '<a class="text-link" href="'+e(secondary['href'])+'">'+e(secondary['label'])+' <span aria-hidden="true">↓</span></a>',hero_html,count=1,flags=re.S)
   hero_html=re.sub(r'<p class="hero-note">.*?</p>','',hero_html,flags=re.S)
   content=hero_html+content[hero_end:]
   content=content.replace('<h1>Pilihan top up game dan voucher <span>Gendut Store</span></h1>','<h1>'+e(p['h1']).replace('Lanjut mabar.','<span>Lanjut mabar.</span>')+'</h1>')
   content=re.sub(r'<section class="benefits wrap".*?</section>','',content,flags=re.S)
  if p['path']=='/' and not p.get('approved_document'):
   tools=re.search(r'<div class="search-tools" id="game-tools" hidden>.*?</div></div>',content,re.S).group(0)
   filters=re.search(r'<div class="filters".*?</div>',tools,re.S).group(0)
   content=content.replace(tools,filters.replace('class="filters"','class="filters" id="game-filters" hidden'))
   content=re.sub(r'<section class="hero wrap">.*?</section>',lambda _:discovery_hero(p,tools.replace(filters,'')),content,count=1,flags=re.S)
  for symbol,shape in [('↗','M4 20 20 4M4 4h16v16'),('↓','M12 4v16M5 13l7 7 7-7')]:
   content=content.replace(symbol,'<svg class="arrow-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="'+shape+'"/></svg>')
  local=p['path'].lstrip('/')+'index.html'
  article_type=p.get('page_type') in ('article','article_index')
  page_head=head(p)
  if article_type:
   page_head=page_head.replace('</head>','<link rel="stylesheet" href="/assets/articles.css"></head>')
   if p.get('page_type')=='article':page_head=page_head.replace('property="og:type" content="website"','property="og:type" content="article"')
   page_header='<a class="skip-link" href="#konten">Langsung ke isi</a><header class="site-header wrap"><a class="brand" href="/" aria-label="Gendut Store, beranda"><img src="/assets/gendut-store-logo.webp" width="800" height="267" alt="Gendut Store"></a><nav aria-label="Navigasi utama"><a href="/artikel/">Artikel</a><a href="/#pilihan-game">Pilihan game</a></nav></header>'
   page_footer='<footer class="site-footer wrap"><p>Gendut Store</p><nav aria-label="Navigasi footer"><a href="/">Beranda</a><a href="/artikel/">Semua artikel</a></nav></footer>'
  else:
   page_head=page_head.replace('</head>','<link rel="stylesheet" href="/assets/landing-refresh.css"></head>').replace('<body>','<body class="landing-page '+('landing-home' if p['path']=='/' else 'landing-game')+'">')
   page_header=header(p['path']=='/');page_footer=footer()
   if any(q.get('page_type')=='article' for q in data['pages']):page_header=page_header.replace('</nav>','<a href="/artikel/">Artikel</a></nav>')
  rendered[local]=page_head+page_header+content+page_footer+'</body></html>'
  rendered[local]=rendered[local].replace('↗','<svg class="arrow-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 20 20 4M4 4h16v16"/></svg>')
 return rendered

if __name__=='__main__':
 data=json.loads((root/'content/site.json').read_text())
 for local,html in render_pages(data).items():
  target=root/'dist'/local;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)
 print('Rendered source pages from public content/site.json.')
